{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 1,
      "verse": 31,
      "text_ar": "ولكنك صنعت هذا الأمر وقتلت أخاك عبثاً لأنه كلمك بالحق، والآن، لذلك، ملعوناً تكون من الأرض التي فتحت فاها لتتقبل دم أخيك من يدهك، والتي فيها دفنته."
    },
    {
      "chapter": 1,
      "verse": 32,
      "text_ar": "ويكون متى فلحتها، فإنها لا تعود تعطيك قوتها كما في البدء، شوكاً وحسكاً تنتج الأرض، وتكون تائهاً وشارداً في الأرض إلى يوم موتك."
    },
    {
      "chapter": 1,
      "verse": 33,
      "text_ar": "وفي ذلك الوقت خرج قاين من حضور الرب، من المكان الذي كان فيه، وذهب تائهاً وشارداً في الأرض نحو شرقي عدن، هو وكل ما يخصه."
    },
    {
      "chapter": 1,
      "verse": 34,
      "text_ar": "وعرف قاين امرأته في تلك الأيام، فحبلت وولدت ابناً، ودعا اسمه أخنوخ، قائلاً: في ذلك الوقت ابتدأ الرب يعطيه راحة وهدوءاً في الأرض."
    },
    {
      "chapter": 1,
      "verse": 35,
      "text_ar": "وفي ذلك الوقت ابتدأ قاين أيضاً يبني مدينة، فبنى المدينة ودعا اسم المدينة أخنوخ، على اسم ابنه، لأنه في تلك الأيام أعطاه الرب راحة على الأرض، فلم يعد يتحرك ويطوف كما في البدء."
    },
    {
      "chapter": 1,
      "verse": 36,
      "text_ar": "وولد لإخنوخ إيراد، وإيراد ولد محويائيل، ومحويائيل ولد متوشائيل."
    },
    {
      "chapter": 2,
      "verse": 1,
      "text_ar": "وكان في السنة المئة والثلاثين لحياة آدم على الأرض، أنه عرف ثانية حواء امرأته، فحبلت وولدت ابناً على شبهه وكصورته، ودعت اسمه شيثاً، قائلة: لأن الله أقام لي نسلاً آخر مكان هابيل، لأن قاين قد قتله."
    },
    {
      "chapter": 2,
      "verse": 2,
      "text_ar": "وعاش شيث مئة وخمس سنين، وولد ابناً، ودعا شيث اسم ابنه أنوش، قائلة: لأنه في ذلك الوقت ابتدأ بنو البشر يكثرون، ويذلون نفوسهم وقلوبهم بتعديهم وعصيانهم لله."
    },
    {
      "chapter": 2,
      "verse": 3,
      "text_ar": "وكان في أيام أنوش أن بني البشر استمروا في العصيان والتعدي على الله، ليزيدوا غضب الرب على بني البشر."
    },
    {
      "chapter": 2,
      "verse": 4,
      "text_ar": "وذاب بنو البشر وخدموا آلهة أخرى، ونسوا الرب الذي خلقهم في الأرض: وفي تلك الأيام صنع بنو البشر تماثيل من نحاس وحديد وخشب وحجر، وسجدوا لها وخدموها."
    }
  ]
}
